function g(r){if(!r)return"";const t=new Date(r);if(Number.isNaN(t.getTime()))return"";const e=Date.now()-t.getTime(),n=60*1e3,a=60*n,o=24*a;if(e<n)return"刚刚";if(e<a)return Math.floor(e/n)+" 分钟前";if(e<o)return Math.floor(e/a)+" 小时前";if(e<2*o)return"昨天";const i=t.getFullYear(),u=String(t.getMonth()+1).padStart(2,"0"),f=String(t.getDate()).padStart(2,"0");return i===new Date().getFullYear()?`${u}-${f}`:`${i}-${u}-${f}`}function s(r){if(!r)return"";const t=new Date(r);if(Number.isNaN(t.getTime()))return"";const e=n=>String(n).padStart(2,"0");return`${t.getFullYear()}-${e(t.getMonth()+1)}-${e(t.getDate())} ${e(t.getHours())}:${e(t.getMinutes())}`}export{s as f,g as t};
